//! Riwāyah profiles (T5.1): what the resolver needs for one riwāyah. Its patch stack (patch
//! files on the Ḥafṣ spine, lowest layer first), its ayah map, and its surah transitions as
//! its source lays them out: per surah, the page lines of its header (surah name, and a
//! basmalah line where the source leaves one). Generated by `pipeline.profiles` (D26).

use serde::{Deserialize, Serialize};

use crate::Error;

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct SurahHeader {
    pub surah: u32,
    pub page: u32,
    pub name_line: u32,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub basmalah_line: Option<u32>,
    /// Set when the basmalah line is a hypothesis, not read from the source (G-023).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub basmalah_evidence: Option<String>,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(try_from = "ProfileWire", into = "ProfileWire")]
pub struct RiwayahProfile {
    pub riwayah: String,
    pub spine: String,
    pub script_id: String,
    /// Pinned source id of the riwāyah's text.
    pub text_source: String,
    pub single_source: bool,
    /// Patch file paths relative to the data root, in layer order.
    pub patch_stack: Vec<String>,
    /// The riwāyah's own ayah numbering; `None` where the spine's numbering is its own (Ḥafṣ).
    pub ayah_map: Option<String>,
    pub surah_headers: Vec<SurahHeader>,
}

#[derive(Clone, Debug, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
struct ProfileWire {
    riwayah: String,
    spine: String,
    script_id: String,
    text_source: String,
    #[serde(default, skip_serializing_if = "std::ops::Not::not")]
    single_source: bool,
    patch_stack: Vec<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    ayah_map: Option<String>,
    surah_headers: Vec<SurahHeader>,
}

impl TryFrom<ProfileWire> for RiwayahProfile {
    type Error = Error;
    fn try_from(w: ProfileWire) -> Result<Self, Error> {
        let at = |m: String| Error::new(format!("profile {}: {m}", w.riwayah));
        for (i, h) in w.surah_headers.iter().enumerate() {
            if i > 0 && w.surah_headers[i - 1].surah >= h.surah {
                return Err(at(format!("surah {} header is out of order", h.surah)));
            }
            if h.basmalah_line.is_some_and(|b| b <= h.name_line) {
                return Err(at(format!("surah {}: basmalah before its name", h.surah)));
            }
            if h.basmalah_evidence.is_some() && h.basmalah_line.is_none() {
                return Err(at(format!("surah {}: evidence without a line", h.surah)));
            }
        }
        let mut stack = w.patch_stack.clone();
        stack.sort();
        stack.dedup();
        if stack.len() != w.patch_stack.len() {
            return Err(at("a patch file is listed twice".into()));
        }
        Ok(RiwayahProfile {
            riwayah: w.riwayah,
            spine: w.spine,
            script_id: w.script_id,
            text_source: w.text_source,
            single_source: w.single_source,
            patch_stack: w.patch_stack,
            ayah_map: w.ayah_map,
            surah_headers: w.surah_headers,
        })
    }
}

impl From<RiwayahProfile> for ProfileWire {
    fn from(p: RiwayahProfile) -> Self {
        ProfileWire {
            riwayah: p.riwayah,
            spine: p.spine,
            script_id: p.script_id,
            text_source: p.text_source,
            single_source: p.single_source,
            patch_stack: p.patch_stack,
            ayah_map: p.ayah_map,
            surah_headers: p.surah_headers,
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::{from_json, from_yaml, to_json};

    const Y: &str = "riwayah: \"r\"\nspine: \"t/v1\"\nscript_id: \"s\"\ntext_source: \"src\"\nsingle_source: true\npatch_stack: [\"patches/raw/r.yaml\"]\nayah_map: \"r\"\nsurah_headers:\n  - {surah: 1, page: 1, name_line: 1}\n  - {surah: 2, page: 2, name_line: 1, basmalah_line: 2, basmalah_evidence: \"e\"}\n";

    #[test]
    fn parses_and_round_trips_through_json() {
        let p: RiwayahProfile = from_yaml(Y).unwrap();
        assert_eq!(p.patch_stack, ["patches/raw/r.yaml"]);
        assert_eq!(p.surah_headers[1].basmalah_line, Some(2));
        let back: RiwayahProfile = from_json(&to_json(&p).unwrap()).unwrap();
        assert_eq!(back, p);
    }

    #[test]
    fn hafs_form_has_no_stack_or_map() {
        let y = "riwayah: \"hafs\"\nspine: \"t/v1\"\nscript_id: \"s\"\ntext_source: \"src\"\npatch_stack: []\nsurah_headers: []\n";
        let p: RiwayahProfile = from_yaml(y).unwrap();
        assert!(!p.single_source && p.ayah_map.is_none() && p.patch_stack.is_empty());
    }

    #[test]
    fn rejects_bad_profiles() {
        for bad in [
            Y.replace("surah: 2,", "surah: 1,"),
            Y.replace("basmalah_line: 2", "basmalah_line: 1"),
            Y.replace("basmalah_line: 2, ", ""),
            Y.replace("[\"patches/raw/r.yaml\"]", "[\"a.yaml\", \"a.yaml\"]"),
            Y.replace("ayah_map", "ayah_mapping"),
        ] {
            assert!(from_yaml::<RiwayahProfile>(&bad).is_err(), "accepted {bad}");
        }
    }
}
